\documentclass[11pt]{article}

\usepackage[a4paper,margin=2.5cm]{geometry}
\usepackage[T1]{fontenc}
\usepackage{lmodern}
\usepackage{amsmath,amssymb,amsthm,mathtools}
\usepackage{microtype}
\usepackage{booktabs}
\usepackage{placeins}
\usepackage{enumitem}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\usepgfplotslibrary{groupplots}
\usepackage[hidelinks]{hyperref}
\usepackage[capitalise,nameinlink]{cleveref}
\usepackage{thmtools}

\input{generated/macros}

\numberwithin{equation}{section}
\declaretheorem[style=plain,numberwithin=section]{theorem}
\declaretheorem[style=plain,sibling=theorem]{proposition}
\declaretheorem[style=plain,sibling=theorem]{lemma}
\declaretheorem[style=remark,sibling=theorem]{remark}
% Section-qualified hyperref anchors, so that equal numbers in different
% sections (and appendices) get distinct link targets.
\renewcommand{\theHequation}{\theHsection.\arabic{equation}}
\renewcommand{\theHtheorem}{\theHsection.\arabic{theorem}}
\providecommand{\theHproposition}{}\renewcommand{\theHproposition}{\theHsection.\arabic{theorem}}
\providecommand{\theHlemma}{}\renewcommand{\theHlemma}{\theHsection.\arabic{theorem}}
\providecommand{\theHremark}{}\renewcommand{\theHremark}{\theHsection.\arabic{theorem}}
\makeatletter
\providecommand*{\toclevel@theorem}{0}
\providecommand*{\toclevel@proposition}{0}
\providecommand*{\toclevel@lemma}{0}
\providecommand*{\toclevel@remark}{0}
\makeatother

% Notation
\newcommand{\N}{\mathbb{N}}
\newcommand{\Z}{\mathbb{Z}}
